B.azJ=new A.a("\u0648\u0641\u064a \u062d\u062f\u064a\u062b \u0645\u0627\u0644\u0643 \u0628\u0646 \u0635\u0639\u0635\u0639\u0629: \u0625\u0646 \u0646\u0628\u064a \u0627\u0644\u0644\u0647 \ufdfa \u062d\u062f\u062b\u0647\u0645 \u0639\u0646 \u0644\u064a\u0644\u0629 \u0623\u0633\u0631\u064a \u064a\u0647\u060c \u0642\u0627\u0644: \u0628\u064a\u0646\u0645\u0627 \u0623\u0646\u0627 \u0641\u064a \u0627\u0644\u062d\u0637\u064a\u0645 -\u0645\u0627 \u0628\u064a\u0646 \u0627\u0644\u0631\u0643\u0646 \u0648\u0627\u0644\u0645\u0642\u0627\u0645- \u0648\u0631\u0628\u0645\u0627 \u0642\u0627\u0644: \u0641\u064a \u0627\u0644\u062d\u062c\u0631 \u0645\u0636\u0637\u062c\u0639\u064b\u0627 \u0625\u0630 \u0623\u062a\u0627\u0646\u064a \u0622\u062a -\u062c\u0628\u0631\u064a\u0644 \u0639\u0644\u064a\u0647 \u0627\u0644\u0633\u0644\u0627\u0645- \u0641\u0642\u062f\u0651\u064e \u0642\u0627\u0644: \u0648\u0633\u0645\u0639\u062a\u0647 \u064a\u0642\u0648\u0644: \u0641\u0634\u0642 \u0645\u0627 \u0628\u064a\u0646 \u0647\u0630\u0647 \u0641\u0642\u0644\u062a \u0644\u0644\u062c\u0627\u0631\u0648\u062f \u0648\u0647\u0648 \u0625\u0644\u0649 \u062c\u0627\u0646\u0628\u064a: \u0645\u0627 \u064a\u0639\u0646\u064a \u0628\u0647\u061f \u0642\u0627\u0644: \u0645\u0646 \u062b\u063a\u0631\u0629 \u0646\u062d\u0631\u0647 -\u0627\u0644\u0645\u0648\u0636\u0639 \u0627\u0644\u0645\u0646\u062e\u0641\u0636 \u0641\u064a \u0623\u062f\u0646\u0649 \u0627\u0644\u0631\u0642\u0628\u0629 \u0645\u0646 \u0627\u0644\u0623\u0645\u0627\u0645- \u0625\u0644\u0649 \u0634\u0639\u0631\u062a\u0647 -\u0634\u0639\u0631 \u0639\u0627\u0646\u062a\u0647- \u0648\u0633\u0645\u0639\u062a\u0647 \u064a\u0642\u0648\u0644: \u0645\u0646 \u0642\u0635\u0647 -\u0631\u0623\u0633 \u0639\u0638\u0627\u0645 \u0627\u0644\u0635\u062f\u0631- \u0625\u0644\u0649 \u0634\u0639\u0631\u062a\u0647\u060c \u0641\u0627\u0633\u062a\u062e\u0631\u062c \u0642\u0644\u0628\u064a \u062b\u0645 \u0623\u062a\u064a\u062a \u0628\u0637\u0633\u062a \u0645\u0646 \u0630\u0647\u0628 \u0645\u0645\u0644\u0648\u0621\u0629 \u0625\u064a\u0645\u0627\u0646\u064b\u0627\u060c \u0641\u063a\u0633\u0644 \u0642\u0644\u0628\u064a \u062b\u0645 \u062d\u064e\u0634\u064a \u062b\u0645 \u0623\u0639\u064a\u062f\u060c \u062b\u0645 \u0623\u062a\u064a\u062a \u0628\u062f\u0627\u0628\u0629 \u062f\u0648\u0646 \u0627\u0644\u0628\u063a\u0644 \u0648\u0641\u0648\u0642 \u0627\u0644\u062d\u0645\u0627\u0631 \u0623\u0628\u064a\u0636 \u0641\u0642\u0627\u0644 \u0644\u0647 \u0627\u0644\u062c\u0627\u0631\u0648\u062f: \u0647\u0648 \u0627\u0644\u0628\u0631\u0627\u0642 \u064a\u0627 \u0623\u0628\u0627 \u062d\u0645\u0632\u0629\u061f \u0642\u0627\u0644 \u0623\u0646\u0633: \u0646\u0639\u0645\u060c \u064a\u0636\u0639 \u062e\u0637\u0648\u0647 \u0639\u0646\u062f \u0623\u0642\u0635\u0649 \u0637\u0631\u0641\u0647 -\u064a\u0636\u0639 \u0631\u062c\u0644\u0647 \u0639\u0646\u062f \u0645\u0646\u062a\u0647\u0649 \u0628\u0635\u0631\u0647.",null)
