B.axY=new A.a("\u0643\u0627\u0646 \u062e\u0631\u0648\u062c \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647  \ufdfa \u0645\u0646 \u0645\u0643\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0642\u062f\u0627\u0645\u060c \u062d\u062a\u0649 \u0644\u0627 \u062a\u0638\u0646 \u0642\u0631\u064a\u0634 \u0623\u0646\u0647 \u064a\u0646\u0648\u064a \u0627\u0644\u062e\u0631\u0648\u062c \u0645\u0646 \u0645\u0643\u0629\u060c \u0644\u0623\u0646\u0647 \u0644\u0648 \u062e\u0631\u062c \u0631\u0627\u0643\u0628\u064b\u0627 \u0641\u0630\u0644\u0643 \u0645\u0645\u0627 \u064a\u062b\u064a\u0631 \u0627\u0644\u0634\u0628\u0647\u0629 \u0648\u0627\u0644\u0634\u0643\u0648\u0643\u060c \u0648\u0623\u0646\u0647 \u064a\u0646\u0648\u064a \u0627\u0644\u062e\u0631\u0648\u062c \u0648\u0627\u0644\u0633\u0641\u0631 \u0625\u0644\u0649 \u062c\u0647\u0629 \u0645\u0627\u060c \u0645\u0645\u0627 \u0642\u062f \u064a\u0639\u0631\u0636\u0647 \u0644\u0644\u0645\u0646\u0639 \u0645\u0646 \u0627\u0644\u062e\u0631\u0648\u062c \u0645\u0646 \u0645\u0643\u0629 \u062f\u0648\u0646 \u0627\u0639\u062a\u0631\u0627\u0636 \u0645\u0646 \u0623\u062d\u062f.",null)
B.aUh=new A.a("\u0648\u0627\u062e\u062a\u064a\u0627\u0631 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0632\u064a\u062f\u064b\u0627 \u0643\u064a \u064a\u0631\u0627\u0641\u0642\u0647 \u0641\u064a \u0631\u062d\u0644\u062a\u0647 \u0641\u064a\u0647 \u062c\u0648\u0627\u0646\u0628 \u0623\u0645\u0646\u064a\u0629\u060c \u0641\u0632\u064a\u062f \u0647\u0648 \u0627\u0628\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0628\u0627\u0644\u062a\u0628\u0646\u064a\u060c \u0641\u0625\u0630\u0627 \u0631\u0622\u0647 \u0645\u0639\u0647 \u0623\u062d\u062f\u060c \u0644\u0627 \u064a\u062b\u064a\u0631 \u0630\u0644\u0643 \u0623\u064a \u0646\u0648\u0639 \u0645\u0646 \u0627\u0644\u0634\u0643 \u0644\u0642\u0648\u0629 \u0627\u0644\u0635\u0644\u0629 \u0628\u064a\u0646\u0647\u0645\u0627\u060c \u0643\u0645\u0627 \u0623\u0646\u0647 \ufdfa \u0639\u0631\u0641 \u0632\u064a\u062f\u064b\u0627 \u0639\u0646 \u0642\u0631\u0628\u060c \u0641\u0639\u0644\u0645 \u0641\u064a\u0647 \u0627\u0644\u0625\u062e\u0644\u0627\u0635 \u0648\u0627\u0644\u0623\u0645\u0627\u0646\u0629 \u0648\u0627\u0644\u0635\u062f\u0642\u060c \u0641\u0647\u0648 \u0625\u0630\u0646 \u0645\u0623\u0645\u0648\u0646 \u0627\u0644\u062c\u0627\u0646\u0628 \u0641\u0644\u0627 \u064a\u0641\u0634\u064a \u0633\u0631\u0651\u064e\u0627\u060c \u0648\u064a\u0639\u062a\u0645\u062f \u0639\u0644\u064a\u0647 \u0641\u064a \u0627\u0644\u0635\u062d\u0628\u0629\u060c \u0648\u0647\u0630\u0627 \u0645\u0627 \u0638\u0647\u0631 \u0639\u0646\u062f\u0645\u0627 \u0643\u0627\u0646 \u064a\u0642\u064a \u0627\u0644\u0646\u0628\u064a \ufdfa \u0627\u0644\u062d\u062c\u0627\u0631\u0629 \u0628\u0646\u0641\u0633\u0647\u060c \u062d\u062a\u0649 \u0623\u0635\u064a\u0628 \u0628\u0634\u062c\u0627\u062c \u0641\u064a \u0631\u0623\u0633\u0647.",null)
B.aDQ=new A.a("\u0648\u0639\u0646\u062f\u0645\u0627 \u0643\u0627\u0646 \u0631\u062f \u0632\u0639\u0645\u0627\u0621 \u0627\u0644\u0637\u0627\u0626\u0641 \u0631\u062f\u064b\u0627 \u0642\u0628\u064a\u062d\u064b\u0627 \u0645\u0634\u0648\u0628\u064b\u0627 \u0628\u0627\u0644\u0627\u0633\u062a\u0647\u0632\u0627\u0621 \u0648\u0627\u0644\u0633\u062e\u0631\u064a\u0629\u060c \u062a\u062d\u0645\u0644\u0647 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0648\u0644\u0645 \u064a\u063a\u0636\u0628 \u0623\u0648 \u064a\u062b\u064f\u0631\u060c \u0628\u0644 \u0637\u0644\u0628 \u0645\u0646\u0647\u0645 \u0623\u0646 \u064a\u0643\u062a\u0645\u0648\u0627 \u0639\u0646\u0647\u060c \u0641\u0647\u0630\u0627 \u062a\u0635\u0631\u0641 \u063a\u0627\u064a\u0629 \u0641\u064a \u0627\u0644\u062d\u064a\u0637\u0629\u060c \u0641\u0625\u0630\u0627 \u0639\u0644\u0645\u062a \u0642\u0631\u064a\u0634 \u0628\u0647\u0630\u0627 \u0627\u0644\u0627\u062a\u0635\u0627\u0644 \u0641\u0625\u0646\u0647\u0627 \u0644\u0627 \u062a\u0633\u062e\u0631 \u0645\u0646\u0647 \u0641\u062d\u0633\u0628\u060c \u0628\u0644 \u0631\u0628\u0645\u0627 \u0634\u062f\u062f\u062a \u0639\u0644\u064a\u0647 \u0641\u064a \u0627\u0644\u0639\u0630\u0627\u0628 \u0648\u0627\u0644\u0627\u0636\u0637\u0647\u0627\u062f\u060c \u0648\u062d\u0627\u0648\u0644\u062a \u0631\u0635\u062f \u062a\u062d\u0631\u0643\u0627\u062a\u0647 \u062f\u0627\u062e\u0644 \u0648\u062e\u0627\u0631\u062c \u0645\u0643\u0629.",null)
