B.aYv=new A.a("\u0643\u0627\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0642\u062f \u0639\u0632\u0645 \u0639\u0644\u0649 \u062f\u062e\u0648\u0644 \u0645\u0643\u0629 \u0645\u0631\u0629 \u062b\u0627\u0646\u064a\u0629\u060c \u063a\u064a\u0631 \u0623\u0646 \u0638\u0627\u0647\u0631 \u0627\u0644\u0623\u062d\u0648\u0627\u0644 \u062a\u062f\u0644 \u0639\u0644\u0649 \u0623\u0646 \u062f\u062e\u0648\u0644 \u0645\u0643\u0629 \u0644\u0645 \u064a\u0643\u0646 \u0623\u0645\u0631\u064b\u0627 \u0647\u064a\u0646\u064b\u0627 \u0648\u0644\u0627 \u0622\u0645\u0646\u064b\u0627\u060c \u0648\u0647\u0646\u0627\u0644\u0643 \u0627\u062d\u062a\u0645\u0627\u0644 \u0643\u0628\u064a\u0631 \u0644\u0644\u063a\u062f\u0631 \u0628\u0647 \u0648\u0644\u0627\u063a\u062a\u064a\u0627\u0644\u0647 \u0645\u0646 \u0642\u0628\u0644 \u0642\u0631\u064a\u0634\u060c \u0627\u0644\u062a\u064a \u0644\u0627 \u064a\u0645\u0643\u0646 \u0623\u0646 \u062a\u0635\u0628\u0631 \u0623\u0643\u062b\u0631\u060c \u0648\u0647\u0648 \u0642\u062f \u0623\u0639\u0644\u0646 \u0627\u0644\u062e\u0631\u0648\u062c \u0639\u0644\u064a\u0647\u0627 \u0648\u0630\u0647\u0628 \u064a\u0633\u062a\u0646\u0635\u0631 \u0628\u0627\u0644\u0642\u0628\u0627\u0626\u0644 \u0627\u0644\u0623\u062e\u0631\u0649\u060c \u0648\u064a\u0648\u0642\u0639 \u0628\u064a\u0646\u0647\u0627 \u0648\u0628\u064a\u0646 \u062d\u0644\u0641\u0627\u0626\u0647\u0627.",null)
B.aPm=new A.a("\u062b\u0645 \u0625\u0646\u0647 \u062d\u062a\u0649 \u0644\u0648 \u0644\u0645 \u062a\u0643\u0646 \u0647\u0646\u0627\u0643 \u062e\u0637\u0648\u0631\u0629 \u0639\u0644\u0649 \u0634\u062e\u0635\u0647\u060c \u0641\u0625\u0646 \u062f\u062e\u0648\u0644\u0647 \u0625\u0644\u0649 \u0645\u0643\u0629 \u0628\u0635\u0648\u0631\u0629 \u0639\u0627\u062f\u064a\u0629 \u0648\u0642\u062f \u0637\u0631\u062f\u062a\u0647 \u0627\u0644\u0637\u0627\u0626\u0641\u060c \u0633\u064a\u062c\u0639\u0644 \u0623\u0647\u0644 \u0645\u0643\u0629 \u064a\u0635\u0648\u0631\u0648\u0646 \u0627\u0644\u0623\u0645\u0631 \u0643\u0647\u0632\u064a\u0645\u0629 \u0643\u0628\u064a\u0631\u0629 \u0623\u0635\u0627\u0628\u062a \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0648\u064a\u062c\u062a\u0631\u0626\u0648\u0646 \u0639\u0644\u064a\u0647\u0645 \u0648\u064a\u0632\u062f\u0627\u062f\u0648\u0646 \u0633\u0641\u0647\u064b\u0627\u060c \u0648\u0644\u0630\u0644\u0643 \u0641\u0642\u062f \u0627\u062a\u062c\u0647 \u0646\u0638\u0631 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0647\u0630\u0647 \u0627\u0644\u0645\u0631\u0629 \u0625\u0644\u0649 \u062a\u0641\u062c\u064a\u0631 \u0645\u0643\u0629 \u0645\u0646 \u0627\u0644\u062f\u0627\u062e\u0644 \u0628\u062f\u0644\u0627\u064b \u0645\u0646 \u062a\u0637\u0648\u064a\u0642\u0647\u0627 \u0645\u0646 \u0627\u0644\u062e\u0627\u0631\u062c\u060c \u0623\u064a \u0623\u0631\u0627\u062f \u0623\u0646 \u064a\u062a\u063a\u0644\u063a\u0644 \u0641\u064a \u062f\u0627\u062e\u0644 \u0628\u0637\u0648\u0646 \u0642\u0631\u064a\u0634 \u0630\u0627\u062a\u0647\u0627\u060c \u0648\u064a\u064f\u0648\u062c\u0650\u062f \u0644\u0647 \u062d\u0644\u0641\u0627\u0621 \u0645\u0646 \u0628\u064a\u0646\u0647\u0645 \u0648\u064e\u064a\u064f\u0643\u064e\u0648\u0651\u0650\u0646 \u0644\u0647 \u0648\u062c\u0648\u062f\u064b\u0627 \u0641\u064a \u0642\u0644\u0628\u0647\u0627.",null)
