B.aUG=new A.a("\u0642\u0627\u0644 \u0645\u0639\u0627\u0630 \u0628\u0646 \u062c\u0628\u0644 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647: \u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa : \u0625\u0646\u0643\u0645 \u0633\u062a\u0623\u062a\u0648\u0646 \u063a\u062f\u0627\u064b \u0625\u0646 \u0634\u0627\u0621 \u0627\u0644\u0644\u0647 \u0639\u064a\u0646 \u062a\u0628\u0648\u0643 \u0648\u0625\u0646\u0643\u0645 \u0644\u0646 \u062a\u0623\u062a\u0648\u0647\u0627 \u062d\u062a\u0649 \u064a\u0636\u062d\u0649 \u0627\u0644\u0646\u0647\u0627\u0631 \u0641\u0645\u0646 \u062c\u0627\u0621\u0647\u0627 \u0645\u0646\u0643\u0645 \u0641\u0644\u0627 \u064a\u0645\u0633 \u0645\u0646 \u0645\u0627\u0626\u0647\u0627 \u0634\u064a\u0626\u0627\u064b \u062d\u062a\u0649 \u0622\u062a\u064a\u060c \u0641\u062c\u0626\u0646\u0627\u0647\u0627 \u0648\u0642\u062f \u0633\u0628\u0642\u0646\u0627 \u0625\u0644\u064a\u0647\u0627 \u0631\u062c\u0644\u0627\u0646 \u0648\u0627\u0644\u0639\u064a\u0646 \u0645\u062b\u0644 \u0627\u0644\u0634\u0631\u0627\u0643 - \u0647\u0648 \u0633\u064a\u0631 \u0627\u0644\u0646\u0639\u0644 \u0648\u0645\u0639\u0646\u0627\u0647 \u0645\u0627\u0621 \u0642\u0644\u064a\u0644 \u062c\u062f\u0627\u064b - \u062a\u0646\u0628\u0636 \u0628\u0634\u064a\u0621 \u0645\u0646 \u0645\u0627\u0644\u060c \u0641\u0633\u0623\u0644\u0647\u0645\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0647\u0644 \u0645\u0633\u062a\u0645\u0627 \u0645\u0646 \u0645\u0627\u0626\u0647\u0627 \u0634\u064a\u0626\u0627\u064b\u061f \u0642\u0627\u0644\u0627: \u0646\u0639\u0645 \u0641\u0633\u0628\u0647\u0645\u0627 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0648\u0642\u0627\u0644 \u0644\u0647\u0645\u0627 \u0645\u0627\u0634\u0627\u0621 \u0627\u0644\u0644\u0647 \u0623\u0646 \u064a\u0642\u0648\u0644 \u062b\u0645 \u063a\u0631\u0641\u0648\u0627 \u0628\u0623\u064a\u062f\u064a\u0647\u0645 \u0645\u0646 \u0627\u0644\u0639\u064a\u0646 \u0642\u0644\u064a\u0644\u0627\u064b \u0642\u0644\u064a\u0644\u0627\u064b\u060c \u062d\u062a\u0649 \u0627\u062c\u062a\u0645\u0639 \u0641\u064a \u0634\u064a\u0621 \u0648\u063a\u0633\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u064a\u0647 \u064a\u062f\u064a\u0647 \u0648\u0648\u062c\u0647\u0647\u060c \u062b\u0645 \u0623\u0639\u0627\u062f\u0647 \u0641\u064a\u0647\u0627 \u0641\u062c\u0631\u062a \u0627\u0644\u0639\u064a\u0646 \u0628\u0645\u0627\u0621 \u0645\u0646\u0647\u0645\u0631 \u0623\u0648 \u063a\u0632\u064a\u0631 \u062d\u062a\u0649 \u0627\u0633\u062a\u0642\u0649 \u0627\u0644\u0646\u0627\u0633.",null)
B.aEY=new A.a("\u0648\u0642\u062f \u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0644\u0645\u0639\u0627\u0630 \u0628\u0646 \u062c\u0628\u0644: \u064a\u0648\u0634\u0643 \u064a\u0627\u0645\u0639\u0627\u0630 \u0625\u0646 \u0637\u0627\u0644\u062a \u0628\u0643 \u062d\u064a\u0627\u0629 \u0623\u0646 \u062a\u0631\u0649 \u0645\u0627 \u0647\u0627\u0647\u0646\u0627 \u0642\u062f \u0645\u0644\u0626 \u062c\u0646\u0627\u0646\u0627\u064b\u060c \u0644\u0642\u062f \u0643\u0627\u0646\u062a \u0645\u0646\u0637\u0642\u0629 \u062a\u0628\u0648\u0643 \u0648\u0627\u0644\u0648\u0627\u062f\u064a \u0627\u0644\u0630\u064a \u0643\u0627\u0646\u062a \u0641\u064a\u0647 \u0627\u0644\u0639\u064a\u0646 \u0645\u0646\u0637\u0642\u0629 \u062c\u0631\u062f\u0627\u0621 \u0644\u0642\u0644\u0629 \u0627\u0644\u0645\u0627\u0621\u060c \u0648\u0644\u0643\u0646 \u0627\u0644\u0644\u0647 \u0639\u0632\u0648\u062c\u0644 \u0623\u062c\u0631\u0649 \u0639\u0644\u0649 \u064a\u062f \u0631\u0633\u0648\u0644\u0647 \ufdfa \u0628\u0631\u0643\u0629 \u062a\u0643\u062b\u064a\u0631 \u0647\u0630\u0627 \u0627\u0644\u0645\u0627\u0621\u060c \u062d\u062a\u0649 \u0623\u0635\u0628\u062d \u064a\u0633\u064a\u0644 \u0628\u063a\u0632\u0627\u0631\u0629 \u0648\u0644\u0645 \u064a\u0643\u0646 \u0647\u0630\u0627 \u0622\u062a\u064a\u0627\u064b \u0644\u0633\u062f \u062d\u0627\u062c\u0629 \u0627\u0644\u062c\u064a\u0634\u060c \u0628\u0644 \u0623\u062e\u0628\u0631 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0628\u0623\u0646\u0647 \u0633\u064a\u0633\u062a\u0645\u0631 \u0648\u0633\u062a\u0643\u0648\u0646 \u0647\u0646\u0627\u0643 \u062c\u0646\u0627\u0646 \u0648\u0628\u0633\u0627\u062a\u064a\u0646 \u0645\u0645\u0644\u0648\u0621\u0629 \u0628\u0627\u0644\u0623\u0634\u062c\u0627\u0631 \u0627\u0644\u0645\u062b\u0645\u0631\u0629\u060c \u0648\u0644\u0642\u062f \u062a\u062d\u0642\u0642 \u0645\u0627 \u0623\u062e\u0628\u0631 \u0628\u0647 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0628\u0639\u062f \u0641\u062a\u0631\u0629 \u0642\u0644\u064a\u0644\u0629 \u0645\u0646 \u0627\u0644\u0632\u0645\u0646\u060c \u0648\u0644\u0627\u0632\u0627\u0644\u062a \u062a\u0628\u0648\u0643 \u062d\u062a\u0649 \u0627\u0644\u064a\u0648\u0645 \u062a\u0645\u062a\u0627\u0632 \u0628\u062c\u0646\u0627\u0646\u0647\u0627 \u0648\u0628\u0633\u0627\u062a\u064a\u0646\u0647\u0627 \u0648\u0646\u062e\u064a\u0644\u0647\u0627 \u0648\u062a\u0645\u0648\u0631\u0647\u0627 \u062a\u0646\u0637\u0642 \u0628\u0635\u062f\u0642 \u0646\u0628\u0648\u0629 \u0627\u0644\u0631\u0633\u0648\u0644 \u0648\u062a\u0634\u0647\u062f \u0628\u0623\u0646 \u0627\u0644\u0631\u0633\u0648\u0644 \u0644\u0627\u064a\u062a\u0643\u0644\u0645 \u0625\u0644\u0627 \u0635\u062f\u0642\u0627\u064b \u0648\u0644\u0627\u064a\u062e\u0628\u0631 \u0625\u0644\u0627 \u062d\u0642\u0627\u064b \u0648\u0644\u0627\u064a\u0646\u0628\u0626 \u0628\u0634\u064a\u0621 \u0625\u0644\u0627 \u0648\u064a\u062a\u062d\u0642\u0642.",null)
