B.aKM=new A.a("\u0639\u0646\u062f\u0645\u0627 \u0634\u0631\u0639 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0641\u064a \u0625\u0645\u0644\u0627\u0621 \u0635\u064a\u063a\u0629 \u0627\u0644\u0645\u0639\u0627\u0647\u062f\u0629 \u0627\u0644\u0645\u062a\u0641\u0642 \u0639\u0644\u064a\u0647\u0627\u060c \u0623\u0645\u0631 \u0627\u0644\u0643\u0627\u062a\u0628 \u0648\u0647\u0648 \u0627\u0644\u0625\u0645\u0627\u0645 \u0639\u0644\u064a \u0628\u0646 \u0623\u0628\u064a \u0637\u0627\u0644\u0628\u060c \u0628\u0623\u0646 \u064a\u0628\u062f\u0623 \u0627\u0644\u0645\u0639\u0627\u0647\u062f\u0629 \u0628\u0643\u0644\u0645\u0629: \u0628\u0633\u0645 \u0627\u0644\u0644\u0647 \u0627\u0644\u0631\u062d\u0645\u0646 \u0627\u0644\u0631\u062d\u064a\u0645\u060c \u0648\u0647\u0646\u0627 \u0627\u0639\u062a\u0631\u0636 \u0631\u0626\u064a\u0633 \u0627\u0644\u0648\u0641\u062f \u0627\u0644\u0642\u0631\u0634\u064a \u0633\u0647\u064a\u0644 \u0628\u0646 \u0639\u0645\u0631\u0648 \u0642\u0627\u0626\u0644\u0627\u064b: \u0644\u0627 \u0623\u0639\u0631\u0641 \u0627\u0644\u0631\u062d\u0645\u0646\u060c \u0627\u0643\u062a\u0628 \u0628\u0627\u0633\u0645\u0643 \u0627\u0644\u0644\u0647\u0645\u060c \u0641\u0636\u062c \u0627\u0644\u0635\u062d\u0627\u0628\u0629 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u0627\u0639\u062a\u0631\u0627\u0636 \u0642\u0627\u0626\u0644\u064a\u0646: \u0647\u0648 \u0627\u0644\u0631\u062d\u0645\u0646 \u0648\u0644\u0627\u0646\u0643\u062a\u0628 \u0625\u0644\u0627\u0651\u064e \u0627\u0644\u0631\u062d\u0645\u0646 \u0648\u0644\u0643\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u062a\u0645\u0634\u064a\u0627\u064b \u0645\u0639 \u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u062d\u0643\u0645\u0629 \u0648\u0627\u0644\u0645\u0631\u0648\u0646\u0629 \u0648\u0627\u0644\u062d\u0644\u0645 \u0642\u0627\u0644 \u0644\u0644\u0643\u0627\u062a\u0628: \u0623\u0643\u062a\u0628 \u0628\u0627\u0633\u0645\u0643 \u0627\u0644\u0644\u0647\u0645\u060c \u0648\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0625\u0645\u0644\u0627\u0621 \u0635\u064a\u063a\u0629 \u0627\u0644\u0645\u0639\u0627\u0647\u062f\u0629 \u0647\u0630\u0647\u060c \u0641\u0623\u0645\u0631 \u0627\u0644\u0643\u0627\u062a\u0628 \u0623\u0646 \u064a\u0643\u062a\u0628 \u0647\u0630\u0627 \u0645\u0627 \u0623\u0635\u0637\u0644\u062d \u0639\u0644\u064a\u0647 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647\u060c \u0648\u0642\u0628\u0644 \u0623\u0646 \u064a\u0643\u0645\u0644 \u0627\u0644\u062c\u0645\u0644\u0629 \u0627\u0639\u062a\u0631\u0636 \u0631\u0626\u064a\u0633 \u0627\u0644\u0648\u0641\u062f \u0627\u0644\u0642\u0631\u0634\u064a \u0639\u0644\u0649 \u0643\u0644\u0645\u0629 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0642\u0627\u0626\u0644\u0627\u064b: \u0644\u0648 \u0623\u0639\u0644\u0645 \u0623\u0646\u0643 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0645\u0627 \u062e\u0627\u0644\u0641\u062a\u0643\u060c \u0648\u0627\u062a\u0628\u0639\u062a\u0643\u060c \u0623\u0641\u062a\u0631\u063a\u0628 \u0639\u0646 \u0627\u0633\u0645\u0643 \u0648\u0627\u0633\u0645 \u0623\u0628\u064a\u0643 \u0645\u062d\u0645\u062f \u0628\u0646 \u0639\u0628\u062f\u0627\u0644\u0644\u0647\u061f \u0627\u0643\u062a\u0628 \u0627\u0633\u0645\u0643 \u0648\u0627\u0633\u0645 \u0627\u0628\u064a\u0643\u060c \u0648\u0627\u0639\u062a\u0631\u0636 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646 \u0639\u0644\u0649 \u0630\u0644\u0643 \u0648\u0644\u0643\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0628\u062d\u0643\u0645\u062a\u0647 \u0648\u062a\u0633\u0627\u0645\u062d\u0647 \u0648\u0628\u0639\u062f \u0646\u0638\u0631\u0647\u060c \u062d\u0633\u0645 \u0627\u0644\u062e\u0644\u0627\u0641 \u0648\u0623\u0645\u0631 \u0627\u0644\u0643\u0627\u062a\u0628 \u0628\u0623\u0646 \u064a\u0634\u0637\u0628 \u0643\u0644\u0645\u0629 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0627\u0644\u0648\u062b\u064a\u0642\u0629 \u0641\u0627\u0644\u062a\u0632\u0645 \u0627\u0644\u0635\u062d\u0627\u0628\u0629 \u0627\u0644\u0635\u0645\u062a \u0648\u0627\u0644\u0647\u062f\u0648\u0621.",null)
