B.aYL=new A.a("\u0645\u0646 \u062d\u062f\u064a\u062b \u062c\u0627\u0628\u0631 \u0628\u0646 \u0639\u0628\u062f\u0627\u0644\u0644\u0647 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0645\u0627 \u0642\u0627\u0644: \u0642\u0627\u0644 \u0644\u0646\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u064a\u0648\u0645 \u0627\u0644\u062d\u062f\u064a\u0628\u064a\u0629: \u0623\u0646\u062a\u0645 \u062e\u064a\u0631 \u0623\u0647\u0644 \u0627\u0644\u0623\u0631\u0636 \u0648\u0643\u0646\u0627 \u0623\u0644\u0641\u0627\u064b \u0648\u0623\u0631\u0628\u0639\u0645\u0627\u0626\u0629 \u0648\u0644\u0648 \u0643\u0646\u062a \u0623\u0628\u0635\u0631 \u0644\u0623\u0631\u064a\u062a\u0643\u0645 \u0645\u0648\u0636\u0639 \u0627\u0644\u0634\u062c\u0631\u0629.",null)
B.aIJ=new A.a("\u0648\u0642\u0627\u0644 \u062c\u0627\u0628\u0631 \u0628\u0646 \u0639\u0628\u062f\u0627\u0644\u0644\u0647 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0645\u0627 \u0623\u062e\u0628\u0631\u062a\u0646\u064a \u0623\u0645 \u0645\u0628\u0634\u0631: \u0623\u0646\u0647\u0627 \u0633\u0645\u0639\u062a \u0627\u0644\u0646\u0628\u064a \ufdfa \u064a\u0642\u0648\u0644 \u0639\u0646\u062f \u062d\u0641\u0635\u0629 : \u0644\u0627\u064a\u062f\u062e\u0644 \u0627\u0644\u0646\u0627\u0631 \u0625\u0646 \u0634\u0627\u0621 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u0634\u062c\u0631\u0629 \u0623\u062d\u062f \u0627\u0644\u0630\u064a\u0646 \u0628\u0627\u064a\u0639\u0648\u0627 \u062a\u062d\u062a\u0647\u0627 \u0642\u0627\u0644\u062a: \u0628\u0644\u0649 \u064a\u0627\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647: \u0641\u0627\u0646\u062a\u0647\u0631\u0647\u0627 \u0641\u0642\u0627\u0644\u062a \u062d\u0641\u0635\u0629: \u0648\u0625\u0646 \u0645\u0646\u0643\u0645 \u0625\u0644\u0627 \u0648\u0627\u0631\u062f\u0647\u0627 \u0641\u0642\u0627\u0644 \u0627\u0644\u0646\u0628\u064a \ufdfa : \u0642\u062f \u0642\u0627\u0644 \u0627\u0644\u0644\u0647 -\u0639\u0632 \u0648\u062c\u0644- : \u0648\u064e\u0625\u0650\u0646\u0652 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u0627 \u0648\u064e\u0627\u0631\u0650\u062f\u064f\u0647\u064e\u0627 \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u064e\u0649 \u0631\u064e\u0628\u0651\u0650\u0643\u064e \u062d\u064e\u062a\u0652\u0645\u064b\u0627 \u0645\u064e\u0642\u0652\u0636\u0650\u064a\u0651\u064b\u0627 \u062b\u064f\u0645\u0651\u064e \u0646\u064f\u0646\u064e\u062c\u0651\u0650\u064a \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u062a\u0651\u064e\u0642\u064e\u0648\u0652\u0627 \u0648\u064e\u0646\u064e\u0630\u064e\u0631\u064f \u0627\u0644\u0638\u0651\u064e\u0627\u0644\u0650\u0645\u0650\u064a\u0646\u064e \u0641\u0650\u064a\u0647\u064e\u0627 \u062c\u0650\u062b\u0650\u064a\u0651\u064b\u0627 - \u0633\u0648\u0631\u0629 \u0645\u0631\u064a\u0645",null)
B.aI9=new A.a("\u0642\u0627\u0644 \u0627\u0644\u0646\u0648\u0648\u064a \u0631\u062d\u0645\u0647 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: \u0642\u0648\u0644\u0647 \ufdfa : \u0644\u0627\u064a\u062f\u062e\u0644 \u0627\u0644\u0646\u0627\u0631 \u0625\u0646 \u0634\u0627\u0621 \u0627\u0644\u0644\u0647 \u0645\u0646 \u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u0634\u062c\u0631\u0629 \u0623\u062d\u062f \u0627\u0644\u0630\u064a\u0646 \u0628\u0627\u064a\u0639\u0648\u0627 \u062a\u062d\u062a\u0647\u0627\u060c \u0642\u0627\u0644 \u0627\u0644\u0639\u0644\u0645\u0627\u0621: \u0645\u0639\u0646\u0627\u0647 \u0644\u0627\u064a\u062f\u062e\u0644\u0647\u0627 \u0623\u062d\u062f \u0645\u0646\u0647\u0645 \u0642\u0637\u0639\u0627\u064b \u0648\u0625\u0646\u0645\u0627 \u0642\u0627\u0644 \u0625\u0646 \u0634\u0627\u0621 \u0627\u0644\u0644\u0647 \u0644\u0644\u062a\u0628\u0631\u0643 \u0644\u0627\u0644\u0644\u0634\u0643 \u0648\u0623\u0645\u0627 \u0642\u0648\u0644 \u062d\u0641\u0635\u0629 \u0628\u0644\u0649 \u0648\u0627\u0646\u062a\u0647\u0627\u0631 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0644\u0647\u0627 \u0641\u0642\u0627\u0644\u062a: \u0648\u064e\u0625\u0650\u0646\u0652 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0625\u0650\u0644\u0627 \u0648\u064e\u0627\u0631\u0650\u062f\u064f\u0647\u064e\u0627 \u0641\u0642\u0627\u0644 \u0627\u0644\u0646\u0628\u064a \ufdfa : \u0648\u0642\u062f \u0642\u0627\u0644: \u062b\u064f\u0645\u0651\u064e \u0646\u064f\u0646\u064e\u062c\u0651\u0650\u064a \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0627\u062a\u0651\u064e\u0642\u064e\u0648\u0652\u0627 \u0641\u064a\u0647 \u062f\u0644\u064a\u0644 \u0644\u0644\u0645\u0646\u0627\u0638\u0631\u0629 \u0648\u0627\u0644\u062c\u0648\u0627\u0628 \u0639\u0644\u0649 \u0648\u062c\u0647 \u0627\u0644\u0627\u0633\u062a\u0631\u0634\u0627\u062f \u0648\u0647\u0648 \u0645\u0642\u0635\u0648\u062f \u062d\u0641\u0635\u0629 \u0644\u0627 \u0623\u0646\u0647\u0627 \u0623\u0631\u0627\u062f\u062a \u0631\u062f \u0645\u0642\u0627\u0644\u062a\u0647 \ufdfa \u0648\u0627\u0644\u0635\u062d\u064a\u062d \u0623\u0646 \u0627\u0644\u0645\u0631\u0627\u062f \u0628\u0627\u0644\u0648\u0631\u0648\u062f \u0641\u064a \u0627\u0644\u0622\u064a\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u0639\u0644\u0649 \u0627\u0644\u0635\u0631\u0627\u0637 \u0648\u0647\u0648 \u062c\u0633\u0631 \u0645\u0646\u0635\u0648\u0628 \u0639\u0644\u0649 \u062c\u0647\u0646\u0645 \u0641\u064a\u0642\u0639 \u0641\u064a\u0647\u0627 \u0623\u0647\u0644\u0647\u0627 \u0648\u064a\u0646\u062c\u0648 \u0627\u0644\u0622\u062e\u0631\u0648\u0646.",null)
B.avk=new A.a("\u0648\u062d\u064a\u0646 \u0646\u0645\u0639\u0646 \u0627\u0644\u0646\u0638\u0631 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u062c\u064a\u0644 \u0627\u0644\u0641\u0631\u064a\u062f \u0645\u0642\u0627\u0631\u0646\u0629 \u0645\u0639 \u0623\u0647\u0644 \u0628\u062f\u0631 \u0646\u0644\u0627\u062d\u0638 \u0627\u0631\u062a\u0641\u0627\u0639 \u0639\u062f\u062f \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u0646\u0635\u0641 \u0645\u0646 \u0627\u0644\u062c\u064a\u0634\u060c \u0648\u0647\u0630\u0627 \u0627\u0644\u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0647\u0627\u0626\u0644 \u0641\u064a \u0639\u062f\u062f \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u064a\u0646 \u0645\u0646 \u062b\u0644\u0627\u062b \u0648\u062b\u0645\u0627\u0646\u064a\u0646 \u0641\u064a \u0628\u062f\u0631 \u0625\u0644\u0649 \u062b\u0645\u0627\u0646\u0645\u0627\u0626\u0629 \u0643\u0627\u0646 \u0645\u0639\u0638\u0645\u0647 \u0645\u0646 \u0627\u0644\u0642\u0628\u0627\u0626\u0644 \u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0627\u0644\u0645\u062c\u0627\u0648\u0631\u0629 \u0648\u0647\u064a \u0642\u0628\u0627\u0626\u0644 \u0635\u063a\u064a\u0631\u0629\u060c \u0625\u0630\u0627 \u0642\u064a\u0633\u062a \u0628\u0627\u0644\u0642\u0628\u0627\u0626\u0644 \u0627\u0644\u0643\u0628\u0631\u0649\u060c \u0644\u0643\u0646 \u0634\u0628\u0627\u0628\u0647\u0627 \u0643\u0627\u0646\u0648\u0627 \u064a\u063a\u062f\u0648\u0646 \u0625\u0644\u0649 \u0627\u0644\u0645\u062f\u064a\u0646\u0629\u060c \u064a\u0646\u0636\u0648\u0648\u0646 \u062a\u062d\u062a \u0644\u0648\u0627\u0621 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u060c \u0648\u064a\u062a\u0644\u0642\u0648\u0646 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0627\u0644\u064a\u0648\u0645\u064a\u0629 \u0641\u064a \u0627\u0644\u0645\u0633\u062c\u062f\u060c \u0648\u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0627\u0644\u0639\u0645\u0644\u064a\u0629 \u0641\u064a \u0627\u0644\u0645\u0639\u0627\u0631\u0643 \u0648\u0627\u0644\u063a\u0632\u0648\u0627\u062a\u060c \u0641\u064a\u062a\u062f\u0631\u0628\u0648\u0646 \u0639\u0644\u0649 \u0627\u0644\u062c\u0646\u062f\u064a\u0629 \u0627\u0644\u062e\u0627\u0644\u0635\u0629 \u0648\u064a\u0641\u0642\u0647\u0648\u0646 \u062f\u064a\u0646\u0647\u0645 \u0645\u0628\u0627\u0634\u0631\u0629 \u0645\u0646 \u0631\u0633\u0648\u0644 \u0631\u0628 \u0627\u0644\u0639\u0627\u0644\u0645\u064a\u0646\u060c \u0648\u064a\u0646\u0634\u0624\u0648\u0646 \u0641\u064a \u0638\u0644\u0627\u0644 \u0627\u0644\u0642\u062f\u0648\u0629 \u0627\u0644\u0639\u0644\u064a\u0627 \u0644\u0647\u0645 \u0645\u0646 \u0627\u0644\u0633\u0627\u0628\u0642\u064a\u0646 \u0627\u0644\u0623\u0648\u0644\u064a\u0646 \u0645\u0646 \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u064a\u0646 \u0648\u0627\u0644\u0623\u0646\u0635\u0627\u0631\u060c \u0648\u064a\u062a\u0646\u0627\u0641\u0633\u0648\u0646 \u0641\u064a \u0627\u0644\u0637\u0627\u0639\u0629 \u0648\u0627\u0644\u0627\u0645\u062a\u062b\u0627\u0644 \u0644\u0623\u0645\u0631 \u0627\u0644\u0644\u0647 \u0648\u0631\u0633\u0648\u0644\u0647\u060c \u0641\u0646\u0627\u0644\u062a \u0642\u0628\u0627\u0626\u0644\u0647\u0645 \u0628\u0630\u0644\u0643 \u0634\u0631\u0641\u0627\u064b \u0631\u0628\u0627 \u0639\u0644\u0649 \u0627\u0644\u0642\u0628\u0627\u0626\u0644 \u0627\u0644\u0643\u0628\u0631\u0649 \u0627\u0644\u062a\u064a \u062a\u062e\u0627\u0630\u0644\u062a \u0641\u064a \u0627\u0644\u0627\u0646\u0636\u0645\u0627\u0645 \u0644\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0641\u0642\u0628\u064a\u0644\u0629 \u0623\u0633\u0644\u0645 \u0648\u063a\u0641\u0627\u0631 \u0643\u0627\u0646\u062a \u0639\u0644\u0649 \u0631\u0623\u0633 \u0647\u0630\u0647 \u0627\u0644\u0642\u0628\u0627\u0626\u0644.",null)
