B.avD=new A.a("\u0628\u0639\u062b \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0645\u0639\u0627\u0630 \u0628\u0646 \u062c\u0628\u0644 \u0627\u0644\u0623\u0646\u0635\u0627\u0631\u064a \u0623\u0639\u0644\u0645 \u0627\u0644\u0635\u062d\u0627\u0628\u0629 \u0641\u064a \u0639\u0644\u0645 \u0627\u0644\u062d\u0644\u0627\u0644 \u0648\u0627\u0644\u062d\u0631\u0627\u0645 \u0625\u0644\u0649 \u0627\u0644\u064a\u0645\u0646 \u0642\u0627\u0636\u064a\u0627\u064b \u0648\u0645\u0641\u0642\u0651\u0650\u0647\u0627\u064b \u0648\u0623\u0645\u064a\u0631\u0627\u064b \u0648\u0645\u0635\u062f\u0651\u0650\u0642\u0627\u064b -\u0622\u062e\u0630 \u0627\u0644\u0632\u0643\u0627\u0629- \u0648\u062c\u0639\u0644\u0647 \u0639\u0644\u0649 \u0623\u062d\u062f \u0645\u0650\u062e\u0652\u0644\u0627\u0641\u064a\u0647\u0627 -\u0627\u0644\u0623\u0642\u0644\u064a\u0645- \u0648\u0647\u0648 \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u0648\u0644\u0645\u0627 \u062e\u0631\u062c \u0645\u0639\u0627\u0630 \u0642\u0627\u0635\u062f\u0627\u064b \u0627\u0644\u064a\u0645\u0646 \u062e\u0631\u062c \u0645\u0639\u0647 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u064a\u0648\u062f\u0639\u0647 \u0648\u064a\u0648\u0635\u064a\u0647 \u0648\u0645\u0639\u0627\u0630 \u0631\u0627\u0643\u0628 \u0648\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u064a\u0645\u0634\u064a \u062a\u062d\u062a \u0631\u0627\u062d\u0644\u062a\u0647\u060c \u0641\u0623\u0648\u0635\u0627\u0647 \u0628\u0648\u0635\u0627\u064a\u0627 \u0643\u062b\u064a\u0631\u0629 \u0648\u0631\u0633\u0645 \u0644\u0647 \u0645\u0646\u0647\u062c\u0627\u064b \u062f\u0639\u0648\u064a\u0627\u064b \u0639\u0638\u064a\u0645\u0627\u064b \u062d\u064a\u062b \u0642\u0627\u0644 \u0644\u0647: \u0625\u0646\u0643 \u0633\u062a\u0623\u062a\u064a \u0642\u0648\u0645\u0627\u064b \u0623\u0647\u0644 \u0643\u062a\u0627\u0628 \u0641\u0625\u0630\u0627 \u062c\u0626\u062a\u0647\u0645 \u0641\u0627\u062f\u0639\u064f\u0647\u0645 \u0625\u0644\u0649 \u0623\u0646 \u064a\u0634\u0647\u062f\u0648\u0627 \u0623\u0646 \u0644\u0627 \u0625\u0644\u0647 \u0625\u0644\u0627 \u0627\u0644\u0644\u0647 \u0648\u0623\u0646 \u0645\u062d\u0645\u062f\u0627\u064b \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647\u060c \u0641\u0625\u0646 \u0647\u0645 \u0623\u0637\u0627\u0639\u0648\u0627 \u0644\u0643 \u0628\u0630\u0644\u0643 \u0641\u0623\u062e\u0628\u0631\u0647\u0645 \u0623\u0646 \u0627\u0644\u0644\u0647 \u0641\u0631\u0636 \u0639\u0644\u064a\u0647\u0645 \u062e\u0645\u0633 \u0635\u0644\u0648\u0627\u062a \u0643\u0644 \u064a\u0648\u0645 \u0648\u0644\u064a\u0644\u0629\u060c \u0641\u0625\u0646 \u0647\u0645 \u0623\u0637\u0627\u0639\u0648\u0627 \u0628\u0630\u0644\u0643 \u0641\u0623\u062e\u0628\u0631\u0647\u0645 \u0623\u0646 \u0627\u0644\u0644\u0647 \u0641\u0631\u0636 \u0639\u0644\u064a\u0647\u0645 \u0635\u062f\u0642\u0629 \u062a\u0624\u062e\u0630 \u0645\u0646 \u0623\u063a\u0646\u064a\u0627\u0626\u0647\u0645 \u0641\u062a\u0631\u062f \u0639\u0644\u0649 \u0641\u0642\u0631\u0627\u0626\u0647\u0645\u060c \u0641\u0625\u0646 \u0647\u0645 \u0623\u0637\u0627\u0639\u0648\u0627 \u0644\u0643 \u0628\u0630\u0644\u0643 \u0641\u0625\u064a\u0627\u0643 \u0648\u0643\u0631\u0627\u0626\u0645 \u0623\u0645\u0648\u0627\u0644\u0647\u0645\u060c \u0648\u0627\u062a\u0642 \u062f\u0639\u0648\u0629 \u0627\u0644\u0645\u0638\u0644\u0648\u0645 \u0641\u0625\u0646\u0647 \u0644\u064a\u0633 \u0628\u064a\u0646\u0647\u0627 \u0648\u0628\u064a\u0646 \u0627\u0644\u0644\u0647 \u062d\u062c\u0627\u0628\u060c \u0648\u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u062d\u062f\u064a\u062b \u0625\u0631\u0634\u0627\u062f \u0645\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0644\u0644\u062f\u0639\u0627\u0629 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u0628\u0627\u0644\u062a\u062f\u0631\u062c \u0648\u0627\u0644\u0628\u062f\u0621 \u0628\u0627\u0644\u0623\u0647\u0645 \u0641\u0627\u0644\u0623\u0647\u0645\u060c \u0641\u0627\u0644\u062f\u0639\u0648\u0629 \u062a\u0643\u0648\u0646 \u0628\u062a\u0631\u0633\u064a\u062e \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u0631\u0633\u0648\u0644\u0647 \u0625\u064a\u0645\u0627\u0646\u0627\u064b \u064a\u062b\u0628\u062a \u0641\u064a \u0627\u0644\u0642\u0644\u0648\u0628 \u0648\u064a\u0647\u064a\u0645\u0646 \u0639\u0644\u0649 \u0627\u0644\u0623\u0641\u0643\u0627\u0631 \u0648\u0627\u0644\u0633\u0644\u0648\u0643\u060c \u062b\u0645 \u062a\u0643\u0648\u0646 \u0627\u0644\u062f\u0639\u0648\u0629 \u0628\u0639\u062f \u0630\u0644\u0643 \u0625\u0644\u0649 \u062a\u0637\u0628\u064a\u0642 \u0623\u0631\u0643\u0627\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0627\u0644\u0639\u0645\u0644\u064a\u0629 \u0627\u0644\u062a\u064a \u062a\u0631\u0633\u062e \u0647\u0630\u0627 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0648\u062a\u0646\u0645\u064a\u0647\u060c \u062b\u0645 \u064a\u0623\u062a\u064a \u0628\u0639\u062f \u0630\u0644\u0643 \u0627\u0644\u0623\u0645\u0631 \u0628\u0627\u0644\u0648\u0627\u062c\u0628\u0627\u062a \u0648\u0627\u0644\u0646\u0647\u064a \u0639\u0646 \u0627\u0644\u0645\u062d\u0631\u0645\u0627\u062a \u0641\u064a\u062a\u0642\u0628\u0644 \u0627\u0644\u0646\u0627\u0633 \u062a\u0643\u0627\u0644\u064a\u0641 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0627\u0644\u062a\u064a \u0642\u062f \u062a\u0643\u0648\u0646 \u0645\u062e\u0627\u0644\u0641\u0629 \u0644\u0647\u0648\u0649 \u0627\u0644\u0646\u0641\u0633 \u0644\u0623\u0646 \u0642\u0644\u0648\u0628\u0647\u0645 \u0642\u062f \u0639\u0645\u0631\u062a \u0628\u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0648\u0627\u0644\u064a\u0642\u064a\u0646 \u0642\u0628\u0644 \u0630\u0644\u0643.",null)
