B.awE=new A.a("\u0644\u0645 \u062a\u0643\u062f \u062a\u0645\u0636\u064a \u0644\u064a\u0627\u0644\u064d \u0642\u0644\u0627\u0626\u0644 \u0639\u0644\u0649 \u0639\u0648\u062f\u0629 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0645\u0646 \u063a\u0632\u0648\u062a\u0647 \u0644\u0628\u0646\u064a \u0644\u062d\u064a\u0627\u0646\u060c \u062d\u062a\u0649 \u0623\u063a\u0627\u0631 \u0639\u064a\u064a\u0646\u0629 \u0628\u0646 \u062d\u0635\u0646 \u0627\u0644\u0641\u0632\u0627\u0631\u064a \u0641\u064a \u062e\u064a\u0644 \u0644\u063a\u0637\u0641\u0627\u0646\u060c \u0643\u0627\u0646 \u0639\u062f\u062f\u0647\u0627 \u0623\u0631\u0628\u0639\u064a\u0646 \u0639\u0644\u0649 \u0644\u0642\u0627\u062d \u0627\u0644\u0625\u0628\u0644 \u0627\u0644\u062d\u0648\u0627\u0645\u0644 \u0630\u0648\u0627\u062a \u0627\u0644\u0623\u0644\u0628\u0627\u0646 \u0644\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0628\u0627\u0644\u063a\u0627\u0628\u0629\u060c \u0648\u0642\u062a\u0644\u0648\u0627 \u0630\u0631 \u0628\u0646 \u0623\u0628\u064a \u0630\u0631 \u0627\u0644\u063a\u0641\u0627\u0631\u064a \u0648\u0623\u0633\u0631\u0648\u0627 \u0632\u0648\u062c\u062a\u0647 \u0644\u064a\u0644\u0649\u060c \u0648\u0627\u0633\u062a\u0627\u0642\u0648\u0627 \u0627\u0644\u0625\u0628\u0644 \u0627\u0644\u062a\u064a \u0639\u062f\u062f\u0647\u0627 \u0639\u0634\u0631\u064a\u0646 \u0648\u0644\u0645\u0627 \u0639\u0644\u0645 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0628\u062e\u0628\u0631 \u0639\u064a\u064a\u0646\u0629\u060c \u062e\u0631\u062c \u0641\u064a \u062e\u0645\u0633\u0645\u0627\u0626\u0629 \u0645\u0646 \u0623\u0635\u062d\u0627\u0628\u0647 \u0641\u064a \u0625\u062b\u0631\u0647\u060c \u0628\u0639\u062f \u0627\u0646 \u0627\u0633\u062a\u062e\u0644\u0641 \u0633\u0639\u062f \u0628\u0646 \u0639\u0628\u0627\u062f\u0629 \u0641\u064a \u062b\u0644\u0627\u062b\u0645\u0627\u0626\u0629 \u0645\u0646 \u0642\u0648\u0645\u0647\u060c \u064a\u062d\u0631\u0633\u0648\u0646 \u0627\u0644\u0645\u062f\u064a\u0646\u0629\u060c \u0648\u0639\u0646\u062f \u062c\u0628\u0644 \u0645\u0646 \u0630\u064a \u0642\u064e\u0631\u062f\u064e \u0623\u062f\u0631\u0643 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0627\u0644\u0639\u062f\u0648 \u0641\u0642\u062a\u0644 \u0628\u0639\u0636 \u0623\u0641\u0631\u0627\u062f\u0647 \u0648\u0627\u0633\u062a\u0646\u0642\u0630 \u0627\u0644\u0625\u0628\u0644.",null)
B.b1C=new A.a("\u0648\u0642\u062f \u0623\u0628\u062f\u0649 \u0633\u0644\u0645\u0629 \u0628\u0646 \u0627\u0644\u0623\u0643\u0648\u0639 \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u0645\u0639\u0631\u0643\u0629 \u0628\u0637\u0648\u0644\u0629 \u0646\u0627\u062f\u0631\u0629 \u0648\u062e\u0627\u0635\u0629 \u0642\u0628\u0644 \u0648\u0635\u0648\u0644 \u0643\u062a\u064a\u0628\u0629 \u0627\u0644\u0641\u0631\u0633\u0627\u0646 \u0627\u0644\u0646\u0628\u0648\u064a\u0629 \u062d\u064a\u062b \u0643\u0627\u0646 \u0645\u0646 \u0638\u0645\u0646 \u0627\u0644\u0631\u0639\u0627\u0629 \u0641\u064a \u0645\u0646\u0637\u0642\u0629 \u0627\u0644\u063a\u0627\u0628\u0629\u060c \u0648\u0638\u0644 \u0628\u0645\u0641\u0631\u062f\u0647 \u064a\u0634\u0627\u063a\u0644 \u0627\u0644\u0645\u063a\u064a\u0631\u064a\u0646 \u0648\u064a\u0631\u0627\u0645\u064a\u0647\u0645 \u0628\u0627\u0644\u0646\u0628\u0644\u060c \u0648\u0643\u0627\u0646 \u0645\u0646 \u0623\u0639\u0638\u0645 \u0627\u0644\u0631\u0645\u0627\u0629 \u0641\u064a \u0639\u0635\u0631\u0647 \u0648\u0642\u062f \u0627\u0633\u062a\u062e\u0644\u0635 \u0645\u062c\u0645\u0648\u0639\u0629 \u0645\u0646 \u0627\u0644\u0625\u0628\u0644 \u0627\u0644\u0645\u0646\u0647\u0648\u0628\u0629 \u0642\u0628\u0644 \u0642\u062f\u0648\u0645 \u0643\u062a\u064a\u0628\u0629 \u0627\u0644\u0641\u0631\u0633\u0627\u0646.",null)
