B.aDX=new A.a("\u0648\u0643\u0627\u0646\u062a \u0642\u0631\u064a\u0634 \u0642\u062f \u0627\u0646\u062d\u062f\u0631\u062a \u0645\u0646 \u0643\u0646\u0627\u0646\u0629 \u0648\u0647\u0645 \u0623\u0648\u0644\u0627\u062f \u0641\u0647\u0631 \u0628\u0646 \u0645\u0627\u0644\u0643 \u0628\u0646 \u0627\u0644\u0646\u0636\u0631 \u0628\u0646 \u0643\u0646\u0627\u0646\u0629\u060c \u0648\u0627\u0646\u0642\u0633\u0645\u062a \u0642\u0631\u064a\u0634 \u0627\u0644\u0649 \u0642\u0628\u0627\u0626\u0644 \u0634\u062a\u0649 \u0645\u0646 \u0623\u0634\u0647\u0631\u0647\u0627 \u062c\u0645\u062d \u0648\u0633\u0647\u0645 \u0648\u0639\u062f\u064a \u0648\u0645\u062e\u0632\u0648\u0645 \u0648\u062a\u064a\u0645 \u0648\u0632\u0647\u0631\u0629\u060c \u0648\u0628\u0637\u0648\u0646 \u0642\u0635\u064a \u0628\u0646 \u0643\u0644\u0627\u0628 \u0648\u0647\u064a \u0639\u0628\u062f\u0627\u0644\u062f\u0627\u0631 \u0628\u0646 \u0642\u0635\u064a \u0648\u0623\u0633\u062f \u0628\u0646 \u0639\u0628\u062f\u0627\u0644\u0639\u0632\u0649 \u0628\u0646 \u0642\u0635\u064a \u0648\u0639\u0628\u062f \u0645\u0646\u0627\u0641 \u0628\u0646 \u0642\u0635\u064a.",null)
B.aJH=new A.a("\u0648\u0643\u0627\u0646 \u0645\u0646 \u0639\u0628\u062f \u0645\u0646\u0627\u0641 \u0623\u0631\u0628\u0639 \u0641\u0635\u0627\u0626\u0644: \u0639\u0628\u062f \u0634\u0645\u0633 \u0648\u0646\u0648\u0641\u0644 \u0648\u0627\u0644\u0645\u0637\u0644\u0628 \u0648\u0647\u0627\u0634\u0645\u060c \u0648\u0628\u064a\u062a \u0647\u0627\u0634\u0645 \u0647\u0648 \u0627\u0644\u0630\u064a \u0627\u0635\u0637\u0641\u0649 \u0627\u0644\u0644\u0647 \u0645\u0646\u0647 \u0633\u064a\u062f\u0646\u0627 \u0645\u062d\u0645\u062f \u0628\u0646 \u0639\u0628\u062f\u0627\u0644\u0644\u0647 \u0628\u0646 \u0639\u0628\u062f\u0627\u0644\u0645\u0637\u0644\u0628 \u0628\u0646 \u0647\u0627\u0634\u0645 \ufdfa \u0648\u0642\u0627\u0644 \ufdfa : \u0625\u0646 \u0627\u0644\u0644\u0647 \u0627\u0635\u0637\u0641\u0649 \u0643\u0646\u0627\u0646\u0629 \u0645\u0646 \u0648\u0644\u062f \u0625\u0633\u0645\u0627\u0639\u064a\u0644 \u0648\u0627\u0635\u0637\u0641\u0649 \u0642\u0631\u064a\u0634\u0627\u064b \u0645\u0646 \u0643\u0646\u0627\u0646\u0629 \u0648\u0627\u0635\u0637\u0641\u0649 \u0645\u0646 \u0642\u0631\u064a\u0634 \u0628\u0646\u064a \u0647\u0627\u0634\u0645 \u0648\u0627\u0635\u0637\u0641\u0627\u0646\u064a \u0645\u0646 \u0628\u0646\u064a \u0647\u0627\u0634\u0645.",null)
