B.aRJ=new A.a("\u0643\u0627\u0646\u062a \u063a\u0632\u0648\u0629 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0648\u0628\u0648\u0627\u0637 \u0647\u0648 \u062c\u0628\u0644 \u0645\u0646 \u062c\u0628\u0627\u0644 \u062c\u0647\u064a\u0646\u0629\u060c \u0628\u0646\u0627\u062d\u064a\u0629 \u0631\u0636\u0648\u0649 \u0628\u0642\u0631\u0628 \u064a\u0646\u0628\u0639\u060c \u0641\u064a \u0634\u0647\u0631 \u0631\u0628\u064a\u0639 \u0627\u0644\u0623\u0648\u0644 \u0641\u064a \u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u062b\u0627\u0646\u064a\u0629 \u0645\u0646 \u0645\u0647\u0627\u062c\u0631\u0647\u060c \u0648\u062e\u0631\u062c \u0641\u064a \u0645\u0627\u0626\u062a\u064a\u0646 \u0645\u0646 \u0623\u0635\u062d\u0627\u0628\u0647 \u0648\u0643\u0627\u0646 \u0645\u0642\u0635\u062f\u0647 \u0623\u0646 \u064a\u0639\u062a\u0631\u0636 \u0639\u064a\u0631\u0627\u064b \u0644\u0642\u0631\u064a\u0634 \u0643\u0627\u0646 \u0641\u064a\u0647\u0627 \u0623\u0645\u064a\u0629 \u0628\u0646 \u062e\u0644\u0641 \u0641\u064a \u0645\u0626\u0629 \u0631\u062c\u0644 \u0648\u0623\u0644\u0641\u064a\u0646 \u0648\u062e\u0645\u0633\u0645\u0627\u0626\u0629 \u0628\u0639\u064a\u0631 \u0641\u0644\u0645 \u064a\u0644\u0642 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0643\u064a\u062f\u0627\u064b \u0641\u0631\u062c\u0639 \u0625\u0644\u0649 \u0627\u0644\u0645\u062f\u064a\u0646\u0629.",null)
B.aDb=new A.a("\u0648\u0623\u0631\u0633\u0644 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0639\u0628\u062f\u0627\u0644\u0644\u0647 \u0628\u0646 \u062c\u062d\u0634 \u0641\u064a \u062b\u0645\u0627\u0646\u064a\u0629 \u0645\u0646 \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u064a\u0646 \u0625\u0644\u0649 \u0646\u062e\u0644\u0629 \u062c\u0646\u0648\u0628 \u0645\u0643\u0629 \u0641\u064a \u0622\u062e\u0631 \u064a\u0648\u0645 \u0645\u0646 \u0631\u062c\u0628 \u0644\u0644\u0627\u0633\u062a\u0637\u0644\u0627\u0639 \u0648\u0627\u0644\u062a\u0639\u0631\u0641 \u0639\u0644\u0649 \u0623\u062e\u0628\u0627\u0631 \u0642\u0631\u064a\u0634 \u0644\u0643\u0646\u0647\u0645 \u062a\u0639\u0631\u0636\u0648\u0627 \u0644\u0642\u0627\u0641\u0644\u0629 \u062a\u062c\u0627\u0631\u064a\u0629 \u0644\u0642\u0631\u064a\u0634 \u0641\u0638\u0641\u0631\u0648\u0627 \u0628\u0647\u0627\u060c \u0648\u0642\u062a\u0644\u0648\u0627 \u0642\u0627\u0626\u062f\u0647\u0627 \u0639\u0645\u0631\u0648 \u0628\u0646 \u0627\u0644\u062d\u0636\u0631\u0645\u064a \u0648\u0623\u0633\u0631\u0648\u0627 \u0627\u062b\u0646\u064a\u0646 \u0645\u0646 \u0631\u062c\u0627\u0644\u0647\u0627 \u0648\u0647\u0645 \u0639\u062b\u0645\u0627\u0646 \u0628\u0646 \u0639\u0628\u062f\u0627\u0644\u0644\u0647 \u0648\u0627\u0644\u062d\u0643\u0645 \u0628\u0646 \u0643\u064a\u0633\u0627\u0646\u060c \u0648\u0639\u0627\u062f\u0648\u0627 \u0628\u0647\u0645 \u0625\u0644\u0649 \u0627\u0644\u0645\u062f\u064a\u0646\u0629\u060c \u0648\u0642\u062f \u062a\u0648\u0642\u0641 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u063a\u0646\u0627\u0626\u0645 \u062d\u062a\u0649 \u0646\u0632\u0644 \u0639\u0644\u064a\u0647 \u0642\u0648\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: \u064a\u064e\u0633\u0652\u0623\u064e\u0644\u064f\u0648\u0646\u064e\u0643\u064e \u0639\u064e\u0646\u0650 \u0627\u0644\u0634\u0651\u064e\u0647\u0652\u0631\u0650 \u0627\u0644\u0652\u062d\u064e\u0631\u064e\u0627\u0645\u0650 \u0642\u0650\u062a\u064e\u0627\u0644\u064d \u0641\u0650\u064a\u0647\u0650 \u0642\u064f\u0644\u0652 \u0642\u0650\u062a\u064e\u0627\u0644\u064c \u0641\u0650\u064a\u0647\u0650 \u0643\u064e\u0628\u0650\u064a\u0631\u064c \u0648\u064e\u0635\u064e\u062f\u0651\u064c \u0639\u064e\u0646\u0652 \u0633\u064e\u0628\u0650\u064a\u0644\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0643\u064f\u0641\u0652\u0631\u064c \u0628\u0650\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u0645\u064e\u0633\u0652\u062c\u0650\u062f\u0650 \u0627\u0644\u0652\u062d\u064e\u0631\u064e\u0627\u0645\u0650 \u0648\u064e\u0625\u0650\u062e\u0652\u0631\u064e\u0627\u062c\u064f \u0623\u064e\u0647\u0652\u0644\u0650\u0647\u0650 \u0645\u0650\u0646\u0652\u0647\u064f \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f \u0639\u0650\u0646\u0652\u062f\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0644\u0652\u0641\u0650\u062a\u0652\u0646\u064e\u0629\u064f \u0623\u064e\u0643\u0652\u0628\u064e\u0631\u064f \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u0642\u064e\u062a\u0652\u0644\u0650 \u0648\u064e\u0644\u0627 \u064a\u064e\u0632\u064e\u0627\u0644\u064f\u0648\u0646\u064e \u064a\u064f\u0642\u064e\u0627\u062a\u0650\u0644\u064f\u0648\u0646\u064e\u0643\u064f\u0645\u0652 \u062d\u064e\u062a\u0651\u064e\u0649 \u064a\u064e\u0631\u064f\u062f\u0651\u064f\u0648\u0643\u064f\u0645\u0652 \u0639\u064e\u0646\u0652 \u062f\u0650\u064a\u0646\u0650\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0650 \u0627\u0633\u0652\u062a\u064e\u0637\u064e\u0627\u0639\u064f\u0648\u0627 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0631\u0652\u062a\u064e\u062f\u0650\u062f\u0652 \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0639\u064e\u0646\u0652 \u062f\u0650\u064a\u0646\u0650\u0647\u0650 \u0641\u064e\u064a\u064e\u0645\u064f\u062a\u0652 \u0648\u064e\u0647\u064f\u0648\u064e \u0643\u064e\u0627\u0641\u0650\u0631\u064c \u0641\u064e\u0623\u064f\u0648\u0644\u064e\u0626\u0650\u0643\u064e \u062d\u064e\u0628\u0650\u0637\u064e\u062a\u0652 \u0623\u064e\u0639\u0652\u0645\u064e\u0627\u0644\u064f\u0647\u064f\u0645\u0652 \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u064f\u0646\u0652\u064a\u064e\u0627 \u0648\u064e\u0627\u0644\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0648\u064e\u0623\u064f\u0648\u0644\u064e\u0626\u0650\u0643\u064e \u0623\u064e\u0635\u0652\u062d\u064e\u0627\u0628\u064f \u0627\u0644\u0646\u0651\u064e\u0627\u0631\u0650 \u0647\u064f\u0645\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 \u062e\u064e\u0627\u0644\u0650\u062f\u064f\u0648\u0646\u064e - \u0633\u0648\u0631\u0629 \u0627\u0644\u0628\u0642\u0631\u0629\u060c \u0641\u0644\u0645\u0627 \u0646\u0632\u0644 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064a\u0645 \u0642\u0628\u0636 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0627\u0644\u0639\u064a\u0631 \u0648\u0627\u0644\u0623\u0633\u064a\u0631\u064a\u0646\u060c \u0648\u0641\u064a \u0633\u0631\u064a\u0629 \u0639\u0628\u062f\u0627\u0644\u0644\u0647 \u0647\u0630\u0647 \u063a\u0646\u0645 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646 \u0623\u0648\u0644 \u063a\u0646\u064a\u0645\u0629\u060c \u0648\u0639\u0645\u0631\u0648 \u0628\u0646 \u0627\u0644\u062d\u0636\u0631\u0645\u064a \u0623\u0648\u0644 \u0642\u062a\u064a\u0644 \u0642\u062a\u0644\u0647 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646\u060c \u0648\u0639\u062b\u0645\u0627\u0646 \u0628\u0646 \u0639\u0628\u062f\u0627\u0644\u0644\u0647 \u0648\u0627\u0644\u062d\u0643\u0645 \u0628\u0646 \u0643\u064a\u0633\u0627\u0646 \u0623\u0648\u0644 \u0645\u0646 \u0623\u0633\u0631 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646.",null)
