B.az7=new A.a("\u0648\u0642\u062f \u0634\u0627\u0639 \u062d\u062f\u064a\u062b \u0630\u0644\u0643 \u0648\u0627\u0646\u062a\u0634\u0631 \u0628\u064a\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0648\u063a\u064a\u0631\u0647\u0645 \u062d\u062a\u0649 \u0628\u0644\u063a \u062f\u0631\u062c\u0629 \u0627\u0644\u0642\u0637\u0639 \u0639\u0646\u062f\u0647\u0645 \u0648\u0628\u0646\u0627\u0621 \u0639\u0644\u064a\u0647 \u0643\u0627\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u064a\u0642\u0648\u0644\u0648\u0646 \u0644\u0623\u0647\u0644 \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0627\u0644\u0645\u0646\u0648\u0631\u0629: \u0625\u0646\u0647 \u0642\u062f \u062a\u0642\u0627\u0631\u0628 \u0632\u0645\u0627\u0646 \u0646\u0628\u064a \u064a\u064f\u0628\u0652\u0639\u062b \u0627\u0644\u0622\u0646 \u0646\u0642\u062a\u0644\u0643\u0645 \u0645\u0639\u0647 \u0642\u0644\u062a \u0639\u0627\u062f\u064d \u0648\u0625\u0631\u0645\u060c \u0648\u0643\u0627\u0646 \u0630\u0644\u0643 \u0627\u0644\u062d\u062f\u064a\u062b \u0633\u0628\u0628\u0627\u064b \u0641\u064a \u0625\u0633\u0644\u0627\u0645 \u0631\u062c\u0627\u0644 \u0645\u0646 \u0627\u0644\u0623\u0646\u0635\u0627\u0631 \u0648\u0642\u062f \u0642\u0627\u0644\u0648\u0627: \u0625\u0646 \u0645\u0645\u0627 \u062f\u0639\u0627\u0646\u0627 \u0627\u0644\u0649 \u0627\u0644\u0627\u0633\u0644\u0627\u0645 \u0645\u0639 \u0631\u062d\u0645\u0629 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u0647\u062f\u0627\u0647 \u0644\u0645\u0627 \u0643\u0646\u0627 \u0646\u0633\u0645\u0639 \u0645\u0646 \u0631\u062c\u0627\u0644 \u0627\u0644\u064a\u0647\u0648\u062f \u0643\u0646\u0627 \u0623\u0647\u0644 \u0634\u0631\u0643 \u0623\u0635\u062d\u0627\u0628 \u0623\u0648\u062b\u0627\u0646 \u0648\u0643\u0627\u0646\u0648\u0627 \u0623\u0647\u0644 \u0643\u062a\u0627\u0628 \u0639\u0646\u062f\u0647\u0645 \u0639\u0644\u0645 \u0644\u064a\u0633 \u0644\u0646\u0627 \u0648\u0643\u0627\u0646\u062a \u0644\u0627 \u062a\u0632\u0627\u0644 \u0628\u064a\u0646\u0646\u0627 \u0648\u0628\u064a\u0646\u0647\u0645 \u0634\u0631\u0648\u0631 \u0641\u0625\u0630\u0627 \u0646\u0644\u0646\u0627 \u0645\u0646\u0647\u0645 \u0628\u0639\u0636 \u0645\u0627\u064a\u0643\u0631\u0647\u0648\u0646 \u0642\u0627\u0644\u0648\u0627 \u0644\u0646\u0627: \u0625\u0646\u0647 \u062a\u0642\u0627\u0631\u0628 \u0627\u0644\u0632\u0645\u0627\u0646 \u0646\u0628\u064a \u064a\u0628\u0639\u062b \u0627\u0644\u0622\u0646 \u0646\u0642\u062a\u0644\u0643\u0645 \u0645\u0639\u0647 \u0642\u062a\u0644 \u0639\u0627\u062f\u064d \u0648\u0625\u0631\u0645.",null)
B.ayX=new A.a("\u0648\u0642\u062f \u0642\u0627\u0644 \u0647\u0631\u0642\u0644 \u0645\u0644\u0643 \u0627\u0644\u0631\u0648\u0645 \u0639\u0646\u062f\u0645\u0627 \u0627\u0633\u062a\u0644\u0645 \u0631\u0633\u0627\u0644\u0629 \u0627\u0644\u0646\u0628\u064a \ufdfa : \u0648\u0642\u062f \u0643\u0646\u062a \u0623\u0639\u0644\u0645 \u0623\u0646\u0647 \u062e\u0627\u0631\u062c \u0644\u0645 \u0623\u0643\u0646 \u0623\u0638\u0646 \u0623\u0646\u0647 \u0645\u0646\u0643\u0645.",null)
